mapper.select:
select
    ${viewParams.viewData},
    to_char(dri.refund_time,'MM') as month,
    sum(COALESCE(dri.refund_amount, 0) * COALESCE(dri.currency_rate,1)) as value
from dmp_refund_info dri

    dri.refund_status = 4

        AND dri.refund_time >= #{params.startTime}


        AND dri.refund_time < #{params.endTime}

    /*平台*/

        AND dri.platform_name IN

            #{platform}


    /*店铺*/

        AND dri.shop_name IN

            #{shopName}


    /*用户id*/

        AND dri.charge_id IN

            #{userId}



group by ${viewParams.groupData}
